def cards(text):
    result={}
    for m in re.finditer(r'^### ([^\n]+)\n([\s\S]*?)(?=^### |\Z)',text,re.M):
        status=re.search(r'Статус:\s*\*\*([^*]+)',m[2])
        if status:result[m[1]]=(status[1],'Научная проверка: да' in m[2])
    return result
